local cases={};local function case(n,f)local ok,e=pcall(f);cases[#cases+1]={name=n,passed=ok,message=ok and"ok"or tostring(e)}end;local function eq(a,b)if a~=b then error(tostring(a).." ~= "..tostring(b),2)end end
local P=load_submission("lua/rhenium_loadout_profiles/profiles.lua");local function fresh(s)return assert(P.new({state=s}))end;local function spec()return{weapons={{class="weapon_pistol",primary={type="Pistol",amount=40}},{class="weapon_smg1",primary={type="SMG1",amount=60},secondary={type="SMG1",amount=10}}}}end
case("multiple named profiles and preferred selection",function()local p=fresh();assert(p:put("a","A","assault",spec(),1));assert(p:put("b","A","backup",{weapons={{class="weapon_crowbar"}}},1));assert(p:select("c","A","assault",1));eq(p:preferred("A"),"assault")end)
case("weapon and ammo allowlists reject unknown values",function()local p=fresh();local ok,c=p:put("a","A","bad",{weapons={{class="weapon_admin"}}},1);assert(not ok);eq(c,"invalid_weapon");ok,c=p:put("b","A","bad2",{weapons={{class="weapon_pistol",primary={type="Nukes",amount=1}}}},1);assert(not ok);eq(c,"invalid_ammo")end)
case("shared ammo is merged once and sorted",function()local p=fresh();assert(p:put("a","A","x",spec(),1));assert(p:select("b","A","x",1));local plan=p:plan("A");eq(plan.ammo[2].type,"SMG1");eq(plan.ammo[2].amount,70)end)
case("ammo caps are checked after aggregation",function()local p=fresh();local s={weapons={{class="weapon_pistol",primary={type="Pistol",amount=120}},{class="weapon_crowbar",secondary={type="Pistol",amount=100}}}};local ok,c=p:put("a","A","x",s,1);assert(not ok);eq(c,"ammo_cap_exceeded")end)
case("primary and secondary ammo remain explicit",function()local p=fresh();assert(p:put("a","A","x",spec(),1));local x=p:get("A","x");assert(x.plan.weapons[2].primary and x.plan.weapons[2].secondary)end)
case("request retries are exact and conflicts fail",function()local p=fresh();assert(p:put("a","A","x",spec(),1));assert(p:put("a","A","x",spec(),1));local ok,c=p:put("a","A","y",spec(),1);assert(not ok);eq(c,"request_conflict")end)
case("profile and preferred revisions reject stale writes",function()local p=fresh();assert(p:put("a","A","x",spec(),2));local ok,c=p:put("b","A","x",spec(),1);assert(not ok);eq(c,"stale_revision");assert(p:select("c","A","x",2));ok,c=p:select("d","A","x",1);assert(not ok);eq(c,"stale_revision")end)
case("profile and weapon count limits are enforced",function()local p=fresh();for i=1,5 do assert(p:put("r"..i,"A","p"..i,{weapons={{class="weapon_crowbar"}}},1))end;local ok,c=p:put("six","A","p6",spec(),1);assert(not ok);eq(c,"profile_limit");ok,c=p:put("many","B","x",{weapons={{class="weapon_crowbar"},{class="weapon_pistol"},{class="weapon_smg1"},{class="weapon_shotgun"},{class="weapon_pistol"}}},1);assert(not ok)end)
case("plans and stored profiles are detached",function()local p=fresh();assert(p:put("a","A","x",spec(),1));assert(p:select("b","A","x",1));local x=p:plan("A");x.weapons[1].class="bad";assert(p:plan("A").weapons[1].class~="bad")end)
case("disconnect retains persistent profiles",function()local p=fresh();assert(p:put("a","A","x",spec(),1));assert(p:select("b","A","x",1));assert(p:disconnect("A",5));assert(p:plan("A"))end)
case("save load preserves preference revisions and replay",function()local p=fresh();assert(p:put("a","A","x",spec(),1));assert(p:select("b","A","x",1));local q=fresh(p:save(9));assert(q:put("a","A","x",spec(),1));eq(q:preferred("A"),"x");eq(q:save(1).last_now,9)end)
case("shutdown is idempotent and freezes writes",function()local p=fresh();assert(p:shutdown());assert(p:shutdown());local ok,c=p:put("a","A","x",spec(),1);assert(not ok);eq(c,"shutdown")end)
case("legal request identifiers freeze parameter and business failures",function()local p=fresh();local bad={weapons={{class="weapon_admin"}}};local ok,c=p:put("failed","A","x",bad,1);assert(not ok);eq(c,"invalid_weapon");ok,c=p:put("failed","A","x",bad,1);assert(not ok);eq(c,"invalid_weapon");ok,c=p:put("failed","A","x",spec(),1);assert(not ok);eq(c,"request_conflict");ok,c=p:select("missing","A","x",1);assert(not ok);eq(c,"not_found");assert(p:put("create","A","x",spec(),1));ok,c=p:select("missing","A","x",1);assert(not ok);eq(c,"not_found")end)
case("malformed persisted profiles choices requests and plans are rejected",function()local p=fresh();assert(p:put("a","A","x",spec(),1));assert(p:select("b","A","x",1));local variants={};local function add(change)local s=p:save(9);change(s);variants[#variants+1]=s end;add(function(s)s.last_now=0/0 end);add(function(s)s.requests="bad"end);add(function(s)local _,r=next(s.requests);if r then r.ok="yes"else s.requests={{id="a",key="x",ok="yes",code="x",data={}}}end end);add(function(s)if s.players then s.players.A.profiles.x.plan.ammo[1].amount=999 else s.profiles[1].plan.ammo[1].amount=999 end end);add(function(s)if s.players then s.players.A.preferred="missing"else s.choices[1].name="missing"end end);add(function(s)if s.profiles then s.profiles[2]=s.profiles[1]else s.players.A.profiles.x.revision=0 end end);for _,s in ipairs(variants)do local loaded,c=P.new({state=s});assert(loaded==nil);eq(c,"invalid_state")end end)
return{cases=cases}
